use serde_json::{Map, Number, Value};
use std::collections::BTreeMap; // not needed
use std::fmt;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Direction { Forward, Reverse }

#[derive(Debug, Clone)]
pub struct Row { pub id: String, pub values: Map<String, Value> }

#[derive(Debug, Clone)]
pub struct FieldChange { pub path: String, pub old: Option<Value>, pub new: Option<Value> }

#[derive(Debug, Clone)]
pub enum Change {
    Add { id: String, value: Map<String, Value> },
    Remove { id: String, value: Map<String, Value> },
    Update { id: String, fields: Vec<FieldChange> },
}
```

