pub fn parse_rows(value: &Value, path: &str) -> Result<Vec<Row>, ApiError> {
    let arr = value.as_array().ok_or_else(|| ApiError::bad_request("expected an array of rows", path))?;
    let mut rows = Vec::with_capacity(arr.len());
    let mut seen = HashSet::new();
    for (i, item) in arr.iter().enumerate() {
        let ipath = format!("{path}/{i}");
        let obj = item.as_object().ok_or(...ipath, "row must be an object")?;
        let id = match obj.get("id") {
            Some(Value::String(s)) if !s.is_empty() => s.clone(),
            Some(Value::String(_)) => return Err(bad("id must be a non-empty string", ipath+"/id")),
            Some(_) => err,
            None => err missing,
        };
        let values = match obj.get("values") {
            Some(Value::Object(m)) => m.clone(),
            Some(_) => err "values must be an object",
            None => err "missing values",
        };
        if !seen.insert(id.clone()) { err duplicate id }
        rows.push(Row{id, values});
    }
    Ok(rows)
}
```

