pub fn apply_changes(rows: Vec<Row>, changes: &[Change], direction: Direction) -> Result<Vec<Row>, ApiError> {
    let mut map: BTreeMap<String, Map> = rows into map (id -> values);
    for change in changes {
        match (change, direction) {
            (Add{id,value}, Forward) => { if map.contains(id) → 409 "row already exists" path /changes/i/id; insert }
            (Add{id,value}, Reverse) => { let cur = map.get → 409 if none; if !obj_eq(cur, value) → 409; remove }
            (Remove, Forward) => { cur must exist, obj_eq(cur, value) else 409; remove }
            (Remove, Reverse) => { must not exist → 409; insert }
            (Update{id,fields}, dir) => {
                let values = map.get_mut(id).ok_or(409)?;
                for (j, field) in fields {
                    apply_field(values, field, dir, path=/changes/i/fields/j)?;
                }
            }
        }
    }
    Ok(map into sorted Vec<Row>)
}
```

