fn unescape(seg: &str) -> Result<String, ()> {
    let mut out = String::with_capacity(seg.len());
    let mut chars = seg.chars();
    while let Some(c) = chars.next() {
        if c == '~' {
            match chars.next() {
                Some('0') => out.push('~'),
                Some('1') => out.push('/'),
                _ => return Err(()),
            }
        } else { out.push(c) }
    }
    Ok(out)
}
