//! Stateless snapshot diffing and bidirectional replay.
//!
//! The HTTP layer only maps JSON in and out; all diff/apply logic lives here.

use serde_json::{Map, Number, Value, json};
use std::collections::{BTreeMap, HashMap, HashSet};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Direction { Forward, Reverse }

#[derive(Debug, Clone)]
pub struct ApiError {
    pub status: u16,
    pub code: &'static str,
    pub message: String,
    pub path: String,
}

impl ApiError {
    fn bad_request(message: impl Into<String>, path: impl Into<String>) -> Self {
        Self { status: 400, code: "bad_request", message: message.into(), path: path.into() }
    }
    fn conflict(message: impl Into<String>, path: impl Into<String>) -> Self {
        Self { status: 409, code: "conflict", message: message.into(), path: path.into() }
    }
}

#[derive(Debug, Clone)]
pub struct Row { id: String, values: Map<String, Value> }

#[derive(Debug, Clone)]
struct FieldChange {
    pointer: String,
    segments: Vec<String>,
    old: Option<Value>,
    new: Option<Value>,
}

#[derive(Debug, Clone)]
enum Change {
    Add { id: String, value: Map<String, Value> },
    Remove { id: String, value: Map<String, Value> },
    Update { id: String, fields: Vec<FieldChange> },
}
impl Change { fn id(&self) -> &str }
