fn parse_changes(value: &Value, path: &str) -> Result<Vec<Change>, ApiError> {
    let arr = value.as_array().ok_or_else(|| ApiError::bad_request("expected an array of changes", path))?;
    let mut changes = Vec::with_capacity(arr.len());
    let mut seen = HashSet::new();
    for (i, item) in arr.iter().enumerate() {
        let base = format!("{path}/{i}");
        let obj = item.as_object().ok_or_else(|| bad("change must be an object", &base))?;
        let id = parse_id(obj, &base)?;
        if !seen.insert(id.clone()) { return Err(bad(format!("duplicate change for id \"{id}\""), format!("{base}/id"))); }
        let op = match obj.get("op") {
            None => return Err(bad("missing \"op\"", format!("{base}/op"))),
            Some(Value::String(s)) => s.as_str(),
            Some(_) => return Err(bad("\"op\" must be a string", ...)),
        };
        let change = match op {
            "add" | "remove" => {
                let value = match obj.get("value") {
                    None => Err missing "value",
                    Some(Value::Object(m)) => Ok(m.clone()),
                    Some(_) => Err("value must be an object"),
                }?;
                if op == "add" { Change::Add{id, value} } else { Change::Remove{id, value} }
            }
            "update" => {
                let fields_v = obj.get("fields").ok_or(missing "/fields")?;
                let fields_arr = fields_v.as_array().ok_or(...)?;
                let mut fields = Vec::new();
                let mut paths = HashSet::new();
                for (j, f) in fields_arr.iter().enumerate() {
                    let fbase = format!("{base}/fields/{j}");
                    let fobj = f.as_object().ok_or(...)?;
                    let pointer = match fobj.get("path") {
                        Some(Value::String(s)) => s.clone(),
                        Some(_) => err "path must be a string",
                        None => err missing "path",
                    };
                    let segments = parse_pointer(&pointer).map_err(|m| bad(m, format!("{fbase}/path")))?;
                    if !paths.insert(pointer.clone()) { err duplicate path }
                    let old = fobj.get("old").cloned();
                    let new = fobj.get("new").cloned();
                    fields.push(FieldChange{pointer, segments, old, new});
                }
                Change::Update{id, fields}
            }
            _ => return Err(bad(format!("unknown op \"{op}\""), format!("{base}/op"))),
        };
        changes.push(change);
    }
    Ok(changes)
}
