pub fn compute_diff(before: &[Row], after: &[Row]) -> Vec<Change> {
    let before_by_id: HashMap<&str, &Row> = before.iter().map(|r| (r.id.as_str(), r)).collect();
    let after_by_id: HashMap<&str, &Row> = ...;
    let mut changes = Vec::new();
    for row in before {
        if !after_by_id.contains_key(row.id.as_str()) {
            changes.push(Change::Remove { id: row.id.clone(), value: row.values.clone() });
        }
    }
    for row in after {
        match before_by_id.get(row.id.as_str()) {
            None => changes.push(Change::Add { id: row.id.clone(), value: row.values.clone() }),
            Some(old) => {
                let mut fields = Vec::new();
                diff_objects(&old.values, &row.values, "", &mut fields);
                if !fields.is_empty() {
                    fields.sort_by(|a, b| a.pointer.cmp(&b.pointer));
                    changes.push(Change::Update { id: row.id.clone(), fields });
                }
            }
        }
    }
    changes.sort_by(|a, b| a.id().cmp(b.id()));
    changes
}

fn diff_objects(old: &Map<String,Value>, new: &Map<String,Value>, prefix: &str, out: &mut Vec<FieldChange>) {
    for (key, old_v) in old {
        let pointer = format!("{prefix}/{}", escape_token(key));
        match new.get(key) {
            None => out.push(FieldChange { segments: vec![], pointer, old: Some(old_v.clone()), new: None }),
            Some(new_v) => match (old_v, new_v) {
                (Value::Object(o), Value::Object(n)) => diff_objects(o, n, &pointer, out),
                _ if !json_eq(old_v, new_v) => out.push(FieldChange { pointer, segments: vec![], old: Some(old_v.clone()), new: Some(new_v.clone()) }),
                _ => {}
            },
        }
    }
    for (key, new_v) in new {
        if !old.contains_key(key) {
            out.push(FieldChange { pointer: format!(...), segments: vec![], old: None, new: Some(new_v.clone()) });
        }
    }
}
