pub fn apply_changes(rows: Vec<Row>, changes: &[Change], direction: Direction) -> Result<Vec<Row>, ApiError> {
    let mut by_id: BTreeMap<String, Map<String, Value>> = rows.into_iter().map(|r| (r.id, r.values)).collect();
    // validate everything first so a failure never leaves a partial result
    for (i, change) in changes.iter().enumerate() {
        validate_change(&by_id, change, direction, &format!("/changes/{i}"))?;
    }
    for change in changes {
        apply_change(&mut by_id, change, direction);
    }
    Ok(by_id.into_iter().map(|(id, values)| Row { id, values }).collect())
}
