fn validate_change(rows: &BTreeMap<...>, change: &Change, dir: Direction, base: &str) -> Result<(), ApiError> {
    match change {
        Change::Add { id, value } => match dir {
            Forward => if rows.contains_key(id) { Err(conflict("row already exists", base/id)) } else {Ok(())},
            Reverse => expect_row(rows, id, value, base),
        },
        Change::Remove { id, value } => match dir {
            Forward => expect_row(...),
            Reverse => must not exist,
        },
        Change::Update { id, fields } => {
            let values = rows.get(id).ok_or_else(|| conflict(format!("row \"{id}\" does not exist"), format!("{base}/id")))?;
            for (j, field) in fields.iter().enumerate() {
                validate_field(values, field, dir, &format!("{base}/fields/{j}"))?;
            }
            Ok(())
        }
    }
}

fn expect_row(rows, id, value, base) -> Result<(),ApiError> {
    match rows.get(id) {
        None => Err(conflict(...does not exist, base/id)),
        Some(cur) if !json_eq(&Value::Object(cur.clone()), &Value::Object(value.clone())) => Err(conflict("row values do not match expected value", base/value)),
        Some(_) => Ok(()),
    }
}
