fn validate_field(values: &Map<String,Value>, field: &FieldChange, dir: Direction, base: &str) -> Result<(), ApiError> {
    let (expected, target, expected_name) = match dir {
        Forward => (&field.old, &field.new, "old"),
        Reverse => (&field.new, &field.old, "new"),
    };
    let current = get_path(values, &field.segments);
    match expected {
        Some(want) => {
            match current {
                None => Err(conflict(format!("no value at \"{}\" to match expected {expected_name} value", field.pointer), format!("{base}/{expected_name}"))),
                Some(got) if !json_eq(got, want) => Err(conflict(...mismatch..., ...)),
                Some(_) => Ok(()),
            }
        }
        None => if current.is_some() { Err(conflict(format!("value already exists at \"{}\"", pointer), base/expected_name)) } else { Ok(()) },
    }?;
    if target.is_some() {
        // every existing intermediate must be an object so the set can proceed
        let mut cur = values;
        for seg in &field.segments[..field.segments.len()-1] {
            match cur.get(seg) {
                None => break,
                Some(Value::Object(m)) => cur = m,
                Some(_) => return Err(conflict(format!("cannot set \"{}\": \"{seg}\" is not an object", field.pointer), format!("{base}/path"))),
            }
        }
    }
    Ok(())
}
