fn apply_change(rows: &mut BTreeMap<String, Map<String,Value>>, change: &Change, dir: Direction) {
    match change {
        Change::Add { id, value } => match dir {
            Forward => { rows.insert(id.clone(), value.clone()); }
            Reverse => { rows.remove(id); }
        },
        Change::Remove { id, value } => match dir {
            Forward => { rows.remove(id); }
            Reverse => { rows.insert(id.clone(), value.clone()); }
        },
        Change::Update { id, fields } => {
            let values = rows.get_mut(id).expect("validated");
            for field in fields {
                let target = match dir { Forward => &field.new, Reverse => &field.old };
                set_path(values, &field.segments, target);
            }
        }
    }
}

fn set_path(values: &mut Map<String,Value>, segs: &[String], target: &Option<Value>) {
    let mut cur = values;
    for seg in &segs[..segs.len()-1] {
        cur = cur.entry(seg.clone()).or_insert_with(|| Value::Object(Map::new()))
            .as_object_mut().expect("validated as object");
    }
    let last = segs.last().expect("non-empty path");
    match target {
        Some(v) => { cur.insert(last.clone(), v.clone()); }
        None => { cur.remove(last); }
    }
}
